from collections import Counter, deque

def longest_runs(vals):
    runs=[]; start=0
    for i in range(1,len(vals)+1):
        if i==len(vals) or vals[i]!=vals[start]:
            runs.append((start,i-1,vals[start])); start=i
    return runs

def spiral(h,w,seeds,base):
    out=[[base]*w for _ in range(h)]
    for r,c,col in seeds:
        # Choose the corner on which the seed lies.
        if r <= h-1-r:
            if c <= w-1-c: # top-left, clockwise
                t,b,l,rr=r,h-1-r,c,w-1-c
                while t<=b and l<=rr:
                    for x in range(l,rr+1): out[t][x]=col
                    for y in range(t,b+1): out[y][rr]=col
                    for x in range(l,rr+1): out[b][x]=col
                    for y in range(t,b+1): out[y][l]=col
                    t+=2;b-=2;l+=2;rr-=2
            else: # top-right, counterclockwise
                t,b,l,rr=r,h-1-r,w-1-c,c
                while t<=b and l<=rr:
                    for x in range(l,rr+1): out[t][x]=col
                    for y in range(t,b+1): out[y][l]=col
                    for x in range(l,rr+1): out[b][x]=col
                    for y in range(t,b+1): out[y][rr]=col
                    t+=2;b-=2;l+=2;rr-=2
        else:
            if c <= w-1-c: # bottom-left, counterclockwise/upward
                t,b,l,rr=h-1-r,r,c,w-1-c
                while t<=b and l<=rr:
                    for x in range(l,rr+1): out[b][x]=col
                    for y in range(t,b+1): out[y][l]=col
                    for x in range(l,rr+1): out[t][x]=col
                    for y in range(t,b+1): out[y][rr]=col
                    t+=2;b-=2;l+=2;rr-=2
            else: # bottom-right
                t,b,l,rr=h-1-r,r,w-1-c,c
                while t<=b and l<=rr:
                    for x in range(l,rr+1): out[b][x]=col
                    for y in range(t,b+1): out[y][rr]=col
                    for x in range(l,rr+1): out[t][x]=col
                    for y in range(t,b+1): out[y][l]=col
                    t+=2;b-=2;l+=2;rr-=2
    return out

